mapper.select:
SELECT r.* FROM erp_finance_report_item r WHERE r.deleted = 0
AND r.ledger_id IN #{ledgerId}
AND r.ledger_id = #{reqVO.ledgerId}
AND r.report_type = #{reqVO.reportType}
AND r.item_category = #{reqVO.itemCategory}
AND r.item_code LIKE CONCAT('%', #{reqVO.itemCode}, '%')
AND r.item_name LIKE CONCAT('%', #{reqVO.itemName}, '%')
AND r.status = #{reqVO.status}

    AND (
        (r.ledger_id != #{ledgerId} OR NOT EXISTS (SELECT 1 FROM erp_finance_report_item_subject s
        WHERE s.item_id = r.id AND s.deleted = 0 AND s.subject_code NOT IN
        #{subjectCode}))
    )

ORDER BY r.sort ASC, r.id ASC
